      {custom.length > 0 && (
        <div class="space-y-1 border-t border-dashed border-[var(--color-paper-3)] pt-2">
          <p class="dept-label">Your own</p>
          {custom.map((s) => (
            <CriterionRow
              key={s.id}
              spec={s}
              onToggle$={props.onToggle$}
              onWeight$={props.onWeight$}
              onRemove$={props.onRemove$}
            />
          ))}
        </div>
