  /* ── Strike the room ───────────────────────────────────────── */

  const clearRoom = $(async () => {
    store.feedback = [];
    store.expandedFeedback = new Set();
    store.repliesByNote = {};
    store.replyNoteId = null;
    store.replyingTo = null;
    window.dispatchEvent(new CustomEvent("twyne:clear-persona-notes"));
    await strikeRoomLocally();
  });

