                  : store.lastProvider}
              </span>
            )}
          </div>
          <h2
            class="mt-0.5 text-xl text-[var(--color-ink)]"
            style="font-family: var(--font-display); font-weight: 600;"
          >
            The Room of Editors
          </h2>
