                ? "var(--color-accent-red)"
                : store.backgroundRoom.status === "reading"
                  ? "var(--color-vermilion)"
                  : "var(--color-ink-muted)",
          }}
        >
          ✦
        </span>
        {backgroundRoomLabel(store.backgroundRoom)}
      </p>
    )}

    {/* ── Mark up my draft + room settings ── */}
    {store.roomSettings.level !== "comments" && (
      <button
