          store.streamingSynthesis,
        )}
      />
    </div>
  )}

  {store.feedback.length === 0 && !store.isGenerating && (
    <div class="text-center py-10 px-4">
      <p
        class="text-3xl"
        style="font-family: var(--font-display); color: var(--color-vermilion);"
      >
