2656	async function readCurrentDraftText(): Promise<string> {
2657	  let draftText = "";
2658	  const receive = (e: Event) => {
2659	    draftText = (e as CustomEvent).detail as string;
2660	  };
2661	  window.addEventListener("twyne:draft-text", receive);
2662	  window.dispatchEvent(new CustomEvent("twyne:request-draft"));
2663	  window.removeEventListener("twyne:draft-text", receive);
2664	  return draftText || (await loadDraftText());
2665	}
