2668	
2669	/**
2670	 * One line describing what the background room is doing. Deliberately states
2671	 * how much more writing it is waiting for, so the cadence never feels
2672	 * arbitrary — a writer who can see "180 more words" understands the room, and
2673	 * a writer watching a silent panel does not.
2674	 */
2675	function backgroundRoomLabel(s: BackgroundRoomSnapshot): string {
2676	  switch (s.status) {
2677	    case "reading":
2678	      return "The room is reading your new pages…";
2679	    case "error":
2680	      return "The room stopped reading — it will try again";
2681	    case "armed": {
2682	      return "The room will read when you pause";
2683	    }
2684	    case "idle":
2685	    default: {
2686	      if (s.passesThisSession >= 1 && s.lastPassAt > 0) {
2687	        return `The room last read ${timeAgo(s.lastPassAt)}`;
2688	      }
2689	      const remaining = Math.max(
2690	        0,
2691	        WORD_DELTA_THRESHOLD - Math.max(0, s.pendingWords),
2692	      );
2693	      return remaining > 0
2694	        ? `The room reads on — ${remaining} more words`
2695	        : "The room is listening";
2696	    }
2697	  }
2698	}
